function WorldMapAtlas.regionAt(x: number, y: number): number
	local g = WorldMapAtlas.Grid
	local gx, gy = math.floor(x / g.cell), math.floor(y / g.cell)
	local row = g.rows[gy + 1]
	if not row or gx < 0 or gx >= g.w then
		return 0
	end
	return tonumber(string.sub(row, gx + 1, gx + 1)) or 0
end

return WorldMapAtlas
